CREATE TABLE schools (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(64) NOT NULL,
    admission_code VARCHAR(32) NOT NULL,
    name VARCHAR(255) NOT NULL,
    short_name VARCHAR(128),
    common_abbreviation VARCHAR(64),
    campus_type VARCHAR(32) NOT NULL DEFAULT 'MAIN_CAMPUS',
    parent_school_id UUID REFERENCES schools(id) ON DELETE SET NULL,
    region VARCHAR(128) NOT NULL,
    status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    data_version VARCHAR(32) NOT NULL DEFAULT '2026',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_schools_code UNIQUE (code),
    CONSTRAINT ck_schools_campus_type CHECK (campus_type IN ('MAIN_CAMPUS', 'BRANCH_CAMPUS')),
    CONSTRAINT ck_schools_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

CREATE INDEX idx_schools_region ON schools(region);
CREATE INDEX idx_schools_campus_type ON schools(campus_type);
CREATE INDEX idx_schools_status ON schools(status);
CREATE INDEX idx_schools_admission_code ON schools(admission_code);

CREATE TABLE major_groups (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(4) NOT NULL,
    name VARCHAR(255) NOT NULL,
    field_code VARCHAR(2),
    regulation_version VARCHAR(32) NOT NULL DEFAULT 'TT_74_2026',
    description VARCHAR(500),
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_major_groups_code UNIQUE (code),
    CONSTRAINT ck_major_groups_code_len CHECK (length(code) = 4)
);

CREATE INDEX idx_major_groups_is_active ON major_groups(is_active);
CREATE INDEX idx_major_groups_field_code ON major_groups(field_code);

